#include <chrono>

int daysBetween(std::chrono::year_month_day from, std::chrono::year_month_day to)
{
    return static_cast<int>((std::chrono::sys_days{ to } - std::chrono::sys_days{ from }).count());
}

bool isWeekend(std::chrono::year_month_day date)
{
    const std::chrono::weekday day{ std::chrono::sys_days{ date } };
    return day == std::chrono::Saturday || day == std::chrono::Sunday;
}

bool isRealDate(int year, int month, int day)
{
    const std::chrono::year_month_day date{ std::chrono::year{ year }, std::chrono::month{ static_cast<unsigned>(month) }, std::chrono::day{ static_cast<unsigned>(day) } };
    return date.ok();
}

