using namespace std::chrono;
TEST("daysBetween") { CHECK_EQ(daysBetween(year{ 2026 } / 1 / 1, year{ 2026 } / 12 / 25), 358); CHECK_EQ(daysBetween(year{ 2024 } / 2 / 28, year{ 2024 } / 3 / 1), 2); CHECK_EQ(daysBetween(year{ 2026 } / 3 / 1, year{ 2026 } / 2 / 28), -1); CHECK_EQ(daysBetween(year{ 2000 } / 1 / 1, year{ 2000 } / 1 / 1), 0); }
TEST("isWeekend") { CHECK(!isWeekend(year{ 2026 } / 11 / 11)); CHECK(isWeekend(year{ 2026 } / 11 / 14)); CHECK(isWeekend(year{ 2026 } / 11 / 15)); CHECK(!isWeekend(year{ 2026 } / 11 / 16)); }
TEST("isRealDate") { CHECK(isRealDate(2024, 2, 29)); CHECK(!isRealDate(2023, 2, 29)); CHECK(!isRealDate(2026, 13, 1)); CHECK(!isRealDate(2026, 4, 31)); CHECK(isRealDate(2026, 12, 31)); }

